#!/usr/bin/env node
// DCC guardrail: Prevent Dangerous Git (PreToolUse, matcher "Bash").
// Deterministic — no LLM call, no network access. Blocks force-push and
// other history-rewriting/destructive git commands regardless of any
// other approved command. Generated by DCC Repository AI Enablement
// onboarding — reviewed, static template, not repo-generated per run.
import { readFileSync } from "node:fs";

const input = JSON.parse(readFileSync(0, "utf8"));
const cmd = String(input?.tool_input?.command ?? "");

const DANGEROUS = [
  /\bgit\s+push\b[^|;&]*(--force\b|-f\b)/,
  /\bgit\s+push\b[^|;&]*--force-with-lease\b/,
  /\bgit\s+reset\s+--hard\b/,
  /\bgit\s+clean\s+.*-[a-z]*f/,
  /\bgit\s+branch\s+-D\b/,
  /\bgit\s+filter-branch\b/,
  /\bgit\s+rebase\s+.*-i\b/,
];

const match = DANGEROUS.find((re) => re.test(cmd));
if (match) {
  process.stderr.write(`DCC guardrail "Prevent Dangerous Git": blocked a destructive/history-rewriting git command (matched ${match}). A human must run this directly if it's genuinely needed.\n`);
  process.exit(2);
}
process.exit(0);
